        <li>📩 Enquiries</li>

        <li>👥 Clients</li>

        <li>📁 Projects</li>

        <li>📊 Analytics</li>

        <li>⚙ Settings</li>

        <li>🚪 Logout</li>

      </ul>

    </div>

  );

}

export default Sidebar;
